examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        listOf(0, 1, 2, 3).forEach { n ->
            MonarchButton(
                text = if (n == 0) "Nobody" else "$n typing",
                onClick = { count = n },
                variant = if (n == count) MonarchButtonVariant.Primary else MonarchButtonVariant.Secondary,
                size = MonarchButtonSize.Sm,
            )
        }
    }
    MonarchTypingIndicator(names = listOf({{typing.0.name}}, "Ben", "Chloé").take(count))
}

